import java.util.*;

public class Main {
    static final String ROOT = "app:1.0";
    static final String[][] EDGES = {
        {"app:1.0", "lib-b:1.0"},
        {"app:1.0", "lib-c:2.0"},
        {"app:1.0", "lib-e:1.0"},
        {"app:1.0", "lib-f:1.0"},
        {"lib-b:1.0", "lib-c:1.0"},
        {"lib-b:1.0", "lib-d:1.0"},
        {"lib-c:2.0", "lib-d:2.0"},
        {"lib-e:1.0", "lib-b:1.0"},
    };

    static String art(String gav) { return gav.substring(0, gav.indexOf(':')); }
    static String ver(String gav) { return gav.substring(gav.indexOf(':') + 1); }

    public static void main(String[] args) {
        Map<String, List<String>> children = new LinkedHashMap<>();
        for (String[] e : EDGES) children.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);

        // BFS 求深度与首次出现序号（决定同深度时的先后）
        Map<String, Integer> depth = new LinkedHashMap<>();
        Map<String, Integer> seq = new LinkedHashMap<>();
        int n = 0;
        depth.put(ROOT, 0);
        seq.put(ROOT, n++);
        Deque<String> q = new ArrayDeque<>(List.of(ROOT));
        while (!q.isEmpty()) {
            String cur = q.poll();
            for (String k : children.getOrDefault(cur, List.of())) {
                if (!depth.containsKey(k)) {
                    depth.put(k, depth.get(cur) + 1);
                    seq.put(k, n++);
                    q.add(k);
                }
            }
        }

        // 调解：每个 artifactId 保留 (depth, seq) 字典序最小者 —— 与 ex01 完全同一套规则
        Map<String, String> winner = new LinkedHashMap<>();
        Map<String, int[]> key = new LinkedHashMap<>();
        for (String g : depth.keySet()) {
            if (g.equals(ROOT)) continue;
            String a = art(g);
            int[] k = {depth.get(g), seq.get(g)};
            int[] cur = key.get(a);
            if (cur == null || k[0] < cur[0] || (k[0] == cur[0] && k[1] < cur[1])) {
                key.put(a, k);
                winner.put(a, g);
            }
        }

        System.out.println("=== mvn dependency:tree -Dverbose (simulated) ===");
        System.out.println(ROOT);
        walk(ROOT, "", winner, children, new LinkedHashSet<>());

        System.out.println();
        System.out.println("=== which node wins, and why ===");
        System.out.println("  lib-c:2.0  depth=1  beats lib-c:1.0  depth=2   (nearest wins)");
        System.out.println("  lib-d:1.0  depth=2  beats lib-d:2.0  depth=2   (same depth -> declared first)");
        System.out.println("  lib-b:1.0  the 2nd occurrence has the SAME version -> duplicate, not conflict");
        System.out.println();
        System.out.println("legend: omitted-for-conflict  = same artifact, DIFFERENT version lost");
        System.out.println("        omitted-for-duplicate = exact same gav is already on the classpath");
    }

    static void walk(String node, String pad, Map<String, String> winner,
                     Map<String, List<String>> children, Set<String> emitted) {
        List<String> kids = children.getOrDefault(node, List.of());
        for (int i = 0; i < kids.size(); i++) {
            String k = kids.get(i);
            boolean last = (i == kids.size() - 1);
            String note;
            boolean recurse;
            if (emitted.contains(k)) {
                note = "   (omitted for duplicate)";
                recurse = false;
            } else if (!k.equals(winner.get(art(k)))) {
                note = "   (omitted for conflict with " + winner.get(art(k)) + ")";
                recurse = false;
            } else {
                note = "";
                recurse = true;
                emitted.add(k);
            }
            System.out.println(pad + (last ? "\\- " : "+- ") + k + note);
            if (recurse) walk(k, pad + (last ? "   " : "|  "), winner, children, emitted);
        }
    }
}
